INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66366975', 66366975, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI TEKNIK PERKERETAAPIAN KELAS I BANDUNG', 'Jasa Pemeriksaan Kegiatan Perawatan dan Perbaikan Pesawat Angkat dan Pesawat Angkut Pada Stasiun Di Wilayah Kerja Balai Teknik Perkeretaapian Kelas I Bandung', 'Jasa Konsultansi', 'E-Purchasing', 'Jawa Barat, Bandung (Kab.)', 1222900000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Balai Teknik Perkeretaapian Kelas I Bandung menerapkan prosedur pemeriksaan teknis yang sistematis melalui jasa pemeriksa dan pengujian teknis sebelum pelaksanaan perawatan untuk memastikan bahwa seluruh unit aset Barang Milik Negara (BMN) ini beroperasi dalam kondisi optimal, aman, dan efisien. Merujuk pada Peraturan Menteri Ketenagakerjaan Nomor 4 Tahun 1995 tentang Perusahaan Jasa Keselamatan dan Kesehatan (PJK3) pemeriksaan dan pengujian teknik adalah pemeriksaan dan pengujian yang dilakukan pada keadaan mesin-mesin, pesawat pesawat, alat-alat dan peralatan kerja, bahan-bahan, lingkungan kerja sifat pekerjaan, cara kerja dan proses produksi. Pemeriksaan lift, eskalator, dan travelator dilakukan oleh Perusahaan Jasa Keselamatan dan Kesehatan Kerja (PJK3) yang mana hal ini telah sesuai dengan Peraturan Menteri Ketenegakerjaan Nomor 4 tahun 1995 tentang Perusahaan Jasa Keselamatan dan Kesehatan kerja yang salah satunya meliputi jasa pemeriksaan dan pengujian teknik. Berdasarkan Peraturan Menteri Pekerjaan Umum Nomor 24/PRT/M/2008 tentang Pedoman Pemeliharaan dan Perawatan Bangunan Gedung dan Peraturan Menteri Ketenagakerjaan Nomor 6 Tahun 2017 tentang Keselamatan dan Kesehatan Kerja Elevator dan Eskalator, dalam konteks stasiun sebagai prasarana perkeretaapian, Balai Teknik Perkeretaapian Kelas I Bandung memfokuskan kegiatan perawatan pada sub-sistem Mekanikal dan Elektrikal. Mengingat pentingnya sistem ini terhadap kelancaran operasional dan standar pelayanan penumpang, maka tahapan pemeriksaan yang dilakukan mengacu pada prosedur teknis yang diatur dalam Peraturan Menteri Perhubungan Nomor 31 Tahun 2011, Peraturan Menteri Perhubungan Nomor 32 Tahun 2011, dan Peraturan Menteri Ketenagakerjaan Nomor 6 Tahun 2017.', 'a. Melaksanakan identifikasi kondisi lift, eskalator, dan travelator untuk memetakan kebutuhan perawatan berkala yang sesuai dengan regulasi seperti penggantian spare parts sesuai kebutuhan; b. Melaksanakan lingkup kegiatan pemeriksaan dan pengujian teknik berdasarkan peraturan yang berlaku dan sesuai dengan hasil inventarisasi kondisi; c. Menyusun rencana jadwal kegiatan perawatan berkala sesuai dengan hasil identifikasi awal; d. Merekomendasikan material/ spare parts/ bahan yang diperlukan untuk perawatan berkala dan/ atau perbaikan serta melaksanakan penggantian sesuai dengan lifetime atau kebutuhan; e. Memastikan pemasangan/ instalasi material/ spare parts/ bahan sesuai dengan persyaratan dan spesifikasi teknis; f. Memastikan performa/kinerja tenaga/teknisi perawatan berkala lift, eskalator, dan travelator; g. Mengantisipasi/mengurangi waktu troubleshooting saat terjadi kerusakan spareparts; h. Menyediakan tenaga pemeriksa yang standby untuk pelaksanaan pendampingan perawatan berkala; i. Menyediakan Engineer on Call untuk keperluan pemeriksaan insidentil terkait dengan response time, resolution time, penanganan insiden dan problem gangguan pada perawatan mekanikal dan elektrikal; j. Memberikan pelatihan (training) / transfer knowledge minimal sebanyak 1 (satu) kali selama masa kontrak untuk mengidentifikasi kejanggalan atau potensi kerusakan sejak dini; k. Melakukan pendampingan kegiatan perawatan berkala untuk menjaga keandalan pada lift, eskalator, dan travelator jika ditemukan permasalahan penyelesaian masalah (problem solving) antara lain: 1) Penyedia jasa bertanggung jawab atas seluruh kegiatan perawatan berkala/ yang dipelihara dengan coverage pekerjaan 1 × 24 jam, termasuk hari libur yang ditetapkan oleh penyedia jasa; 2) Gangguan/permasalahan terhadap gangguan peralatan di stasiun yang dikelola dibedakan menjadi dua kategori, meliputi: a) Gangguan/permasalahan yang berdampak pada layanan, yaitu gangguan/permasalahan yang menyebabkan pelayanan penumpang di stasiun di dalamnya terganggu; b) Gangguan/permasalahan yang tidak berdampak pada layanan, yaitu gangguan/permasalahan namun tidak menyebabkan pelayanan penumpang di dalamnya terganggu. 3) Dalam hal penyelesaian gangguan/masalah terhadap permasalahan di stasiun, penyedia jasa pemeriksa wajib melakukan pendampingan dengan memenuhi ketentuan sebagai berikut: a) Response time atau waktu yang dibutuhkan untuk merespon adanya masalah hingga dapat diselesaikan adalah maksimal 30 menit, yang dihitung sejak laporan gangguan diterima oleh penyedia jasa sampai ada tindakan penanganan kerusakan tersebut; b) Resolution time atau waktu maksimal penyelesaian masalah yang berdampak pada layanan adalah maksimal 1x8 jam, dan penanganan gangguan/permasalahan yang tidak berdampak pada layanan adalah maksimal 1x24 jam, dihitung sejak laporan gangguan diterima penyedia sampai elevator/eskalator yang mengalami gangguan dapat diperbaiki dan beroperasi normal kembali. 4) Menyediakan layanan sesuai dengan struktur organisasi Call Tree Handling problem dan senantiasa berkoordinasi dengan tim satker; 5) Menyediakan laporan dokumentasi permasalahan dan solusi yang dilakukan terhadap pekerjaan yang dikelola. l. Menyampaikan laporan yang telah mendapatkan verifikasi dan persetujuan jasa pemeriksa dan/atau pihak Balai Teknik Perkeretaapaian Kelas I Bandung sebagai dasar penandatanganan Berita Acara Serah Terima (BAST) pekerjaan. Adapun laporan yang perlu disampaikan adalah sebagai berikut: 1) Laporan Bulanan; 2) Dokumentasi pekerjaan perawatan berkala; 3) Laporan hasil analisa dan rekomendasi dalam rangka optimalisasi performance pada akhir pekerjaan; 4) Surat Keterangan Memenuhi Persyaratan Keselamatan dan Kesehatan Kerja (SILO). m. Melaksanakan koordinasi antar tim untuk meningkatkan kinerja, berkomunikasi, dan berkoordinasi untuk menjamin ketersediaan informasi bagi seluruh stakeholder dan mencari solusi permasalahan; n. Serah Terima Pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2721522);
