INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66407583', 66407583, 'analyze_legacy', 'Badan Pengawas Pemilihan Umum', 'central', 'SEKRETARIAT BAWASLU KABUPATEN MAJALENGKA', 'Paket Pengadaan Sewa Kendaraan 12 Bulan di Bawaslu Majalengka', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Majalengka (Kab.)', 68040000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pekerjaan ini meliputi penyediaan kendaraan roda 4 (empat) untuk mendukung kegiatan operasional melalui sistem sewa selama 12 (dua belas) bulan. Kendaraan yang disediakan harus dalam kondisi baik dan layak digunakan serta memenuhi spesifikasi teknis yang telah ditentukan. Penyedia bertanggung jawab menyediakan kendaraan lengkap dengan perlengkapan standar kendaraan, seperti ban cadangan, dongkrak, buku manual, dan perlengkapan lainnya. Selain itu, kendaraan harus dilengkapi dengan dokumen resmi yang masih berlaku, seperti STNK dan dokumen kendaraan lainnya. Kendaraan diserahkan kepada pengguna dalam kondisi baik, bersih, dan siap digunakan selama masa sewa berlangsung. Penyedia juga bertanggung jawab memastikan kendaraan tetap dalam kondisi baik selama masa sewa.', 'Pengadaan kendaraan roda 4 ini dimaksudkan untuk mendukung kegiatan operasional. Kendaraan yang disediakan harus dalam kondisi baru (brand new), bukan kendaraan bekas atau rekondisi, dengan tahun pembuatan minimal tahun berjalan atau paling lama satu tahun sebelumnya. Kendaraan merupakan mobil penumpang dengan kapasitas minimal 5 (lima) orang termasuk pengemudi. Kendaraan dilengkapi dengan mesin berbahan bakar bensin atau diesel dengan kapasitas minimal 1.300 cc dan menggunakan sistem bahan bakar fuel injection serta sistem pendingin mesin radiator atau water cooled. Sistem transmisi kendaraan dapat berupa manual atau otomatis dengan minimal 5 percepatan sehingga dapat digunakan secara optimal untuk kegiatan operasional. Dari segi keselamatan, kendaraan harus dilengkapi dengan sabuk pengaman (seat belt) untuk pengemudi dan penumpang, minimal dua airbag, serta sistem pengereman yang dilengkapi dengan teknologi ABS atau setara untuk meningkatkan keamanan selama berkendara. Selain itu, kendaraan harus memiliki fitur pendukung seperti Air Conditioner (AC), power steering, power window, central lock, serta sistem audio sebagai perlengkapan standar kendaraan. Kendaraan juga harus dilengkapi dengan ban cadangan, dongkrak, dan peralatan standar kendaraan lainnya. Pada saat penyerahan, kendaraan wajib dilengkapi dengan dokumen resmi berupa STNK, BPKB, faktur kendaraan, buku manual, serta buku servis atau garansi resmi dari pabrikan. Kendaraan yang diserahkan harus dalam kondisi baik, siap digunakan, dan mendapatkan garansi resmi dari pabrikan minimal 3 (tiga) tahun atau 100.000 km, mana yang tercapai lebih dahulu.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2722720);
